import java.util.*;
public class BearCompanyVariant2 {
    static int countV, countK, countS;
    static int[][] freqTable;
    static ArrayList<Integer>[] indexLists;
    static int[][][][] cache;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String inputStr = sc.next();
        char[] chars = inputStr.toCharArray();
        countV = countK = countS = 0;
        freqTable = new int[n + 1][3];
        indexLists = new ArrayList[3];
        for (int i = 0; i < 3; i++) indexLists[i] = new ArrayList<>();
        int position = 0;
        for (char ch : chars) {
            System.arraycopy(freqTable[position], 0, freqTable[position + 1], 0, 3);
            position++;
            if (ch == 'V') {
                freqTable[position][0]++;
                countV++;
                indexLists[0].add(position);
            } else if (ch == 'K') {
                freqTable[position][1]++;
                countK++;
                indexLists[1].add(position);
            } else {
                freqTable[position][2]++;
                countS++;
                indexLists[2].add(position);
            }
        }
        cache = new int[countV + 1][countK + 1][countS + 1][3];
        for (int[][][] arr3D : cache) for (int[][] arr2D : arr3D) for (int[] arr1D : arr2D) Arrays.fill(arr1D, -1);
        System.out.println(compute(0, 0, 0, 2));
    }

    static int compute(int v, int k, int s, int last) {
        if (v == countV && k == countK && s == countS) return 0;
        if (cache[v][k][s][last] != -1) return cache[v][k][s][last];
        int result = Integer.MAX_VALUE;
        if (v < countV) {
            int p = indexLists[0].get(v);
            int cost = Math.max(freqTable[p][0] - v, 0) + Math.max(freqTable[p][1] - k, 0) + Math.max(freqTable[p][2] - s, 0) - 1;
            result = Math.min(result, compute(v + 1, k, s, 0) + cost);
        }
        if (k < countK && last != 0) {
            int p = indexLists[1].get(k);
            int cost = Math.max(freqTable[p][0] - v, 0) + Math.max(freqTable[p][1] - k, 0) + Math.max(freqTable[p][2] - s, 0) - 1;
            result = Math.min(result, compute(v, k + 1, s, 1) + cost);
        }
        if (s < countS) {
            int p = indexLists[2].get(s);
            int cost = Math.max(freqTable[p][0] - v, 0) + Math.max(freqTable[p][1] - k, 0) + Math.max(freqTable[p][2] - s, 0) - 1;
            result = Math.min(result, compute(v, k, s + 1, 2) + cost);
        }
        return cache[v][k][s][last] = result;
    }
}
